8: /**
9:  * Refresh-token rotation with reuse detection.
10:  *
11:  * Storage: tokenHash = SHA-256(rawToken + pepper), plus a sessionId that
12:  * links every token in one login chain.
13:  * Rotation: one transaction marks the old row revoked and inserts the new.
14:  * Reuse detection: presenting an already-rotated token revokes the WHOLE
15:  * chain, which is the standard response -- the presenter is either the
16:  * legitimate client replaying, or an attacker holding a stolen copy, and
17:  * there is no way to tell which, so both lose the session.
18:  */
19: 
20: /**
21:  * Boot-time assertion that the pepper was overridden away from the
22:  * committed placeholder in any non-development environment.
23:  *
24:  * Fails CLOSED on an unset NODE_ENV. An environment that has not said what
25:  * it is does not get the benefit of the doubt on a secret that is published
26:  * in the source tree.
27:  */
28: export function assertPepperConfigured() {
29:   const pepper = getPepper(); // throws when missing or empty
30:   const env = process.env.NODE_ENV;
31:   const isDev = env === "development";
32:   if (!isDev && pepper === DEV_PEPPER_PLACEHOLDER) {
33:     const reason =
34:       env == null
35:         ? "NODE_ENV is unset (treated as non-dev; export NODE_ENV=development if that is what you meant)"
36:         : `NODE_ENV=${env} is not 'development'`;
37:     throw new Error(
38:       `refresh token pepper is set to the committed dev placeholder but ${reason}. ` +
39:         "Set REFRESH_TOKEN_PEPPER to a real secret in this environment.",
40:     );
41:   }
42: }
