44: /** Deterministic so the verify path can look up by hash directly. */
45: export function hashToken(rawToken) {
46:   if (typeof rawToken !== "string" || rawToken.length === 0) {
47:     throw new Error("rawToken must be a non-empty string");
48:   }
49:   return crypto
50:     .createHash("sha256")
51:     .update(rawToken + getPepper())
52:     .digest("hex");
53: }
54: 
55: export function generateRawToken() {
56:   return crypto.randomBytes(32).toString("hex");
57: }
58: 
59: /** Issue a fresh chain at login. Returns the raw token for the client. */
60: export async function issueChain(store, userId, now = new Date()) {
61:   if (!Number.isInteger(userId) || userId <= 0) {
62:     throw new Error("userId must be a positive integer");
63:   }
64:   const rawToken = generateRawToken();
65:   const sessionId = crypto.randomUUID();
66:   const expiresAt = new Date(now.getTime() + getLifetimeMs());
67:   store.insert({ tokenHash: hashToken(rawToken), sessionId, userId, expiresAt });
68:   return { rawToken, sessionId, expiresAt };
69: }
70: 
71: /**
72:  * Rotate a refresh token.
73:  *
74:  *   1. Lock the row by tokenHash (serialises concurrent rotations).
75:  *   2. chainRevokedAt set            -> CHAIN_REVOKED
76:  *   3. revokedAt set                 -> TOKEN_REUSE_DETECTED, and every row
77:  *                                       in the session is chain-revoked
78:  *   4. expiry missing or unparseable -> TOKEN_EXPIRED
79:  *   5. otherwise insert the successor and revoke the predecessor
80:  *
81:  * Without the row lock in step 1, two concurrent rotations of the same hash
82:  * both pass the revoked check, both insert a successor, and the chain ends
83:  * up with two parallel valid tokens -- which breaks the single-active-
84:  * successor invariant that reuse detection depends on.
85:  */
86: export async function rotate(store, rawToken, expectedUserId) {
87:   if (typeof rawToken !== "string" || rawToken.length === 0) {
88:     return { err: { code: "TOKEN_NOT_FOUND" } };
89:   }
90:   // A throw from hashToken here can only be a pepper misconfiguration.
91:   // Letting it propagate is deliberate: reporting a config fault as
92:   // TOKEN_NOT_FOUND would disguise an outage as a client error.
93:   const tokenHash = hashToken(rawToken);
94: 
95:   return store.transaction(async (trx) => {
96:     const row = await trx.lockByHash(tokenHash);
97:     if (!row) return { err: { code: "TOKEN_NOT_FOUND" } };
98: 
99:     // One `now` for every check and write in the transaction, so a slow
100:     // transaction cannot compare against two different clocks.
101:     const now = new Date();
102: 
103:     if (row.chainRevokedAt) return { err: { code: "CHAIN_REVOKED" } };
104: 
105:     if (row.revokedAt) {
106:       trx.updateBySession(row.sessionId, { chainRevokedAt: now });
107:       return { err: { code: "TOKEN_REUSE_DETECTED" } };
108:     }
109: 
110:     if (
111:       typeof expectedUserId === "number" &&
112:       expectedUserId > 0 &&
113:       row.userId !== expectedUserId
114:     ) {
115:       return { err: { code: "USER_MISMATCH" } };
116:     }
117: 
118:     // Fail closed on every invalid expiry shape, not just the expected one.
119:     // A driver may hand back a Date, an ISO string, null, or junk; the
120:     // schema is not the only thing standing between a user and a token that
121:     // never expires.
122:     if (!row.expiresAt) return { err: { code: "TOKEN_EXPIRED" } };
123:     const expiresAtMs = new Date(row.expiresAt).getTime();
124:     if (!Number.isFinite(expiresAtMs) || expiresAtMs <= now.getTime()) {
125:       return { err: { code: "TOKEN_EXPIRED" } };
126:     }
127: 
128:     const nextRawToken = generateRawToken();
129:     const nextHash = hashToken(nextRawToken);
130:     const nextExpiresAt = new Date(now.getTime() + getLifetimeMs());
131: 
132:     trx.insert({
133:       tokenHash: nextHash,
134:       sessionId: row.sessionId,
135:       userId: row.userId,
136:       expiresAt: nextExpiresAt,
137:     });
138:     trx.updateByHash(tokenHash, {
139:       revokedAt: now,
140:       replacedByTokenHash: nextHash,
141:     });
142: 
143:     return {
144:       data: {
145:         rawToken: nextRawToken,
146:         sessionId: row.sessionId,
147:         expiresAt: nextExpiresAt,
148:         userId: row.userId,
149:       },
150:     };
151:   });
152: }
153: 
154: /**
155:  * Revoke every row in the chain the token belongs to. Used by explicit
156:  * logout. Returns false when the token matches nothing, and also when the
157:  * chain was already revoked -- the caller learns whether THIS call was what
158:  * revoked it.
159:  */
160: export async function revokeChain(store, rawToken) {
161:   if (typeof rawToken !== "string" || rawToken.length === 0) return false;
162:   let tokenHash;
163:   try {
164:     tokenHash = hashToken(rawToken);
165:   } catch {
166:     return false;
167:   }
168:   const row = store.findByHash(tokenHash);
169:   if (!row || row.chainRevokedAt) return false;
170:   store.updateBySession(row.sessionId, { chainRevokedAt: new Date() });
171:   return true;
172: }

