1: // Configuration for the refresh-token subsystem.
2: //
3: // The pepper is a per-ENVIRONMENT secret mixed into the token hash before
4: // storage. It is not a salt: a salt is per-row and stored beside the hash,
5: // a pepper is global and deliberately kept OUT of the database, so a dump
6: // of the token table is not enough to verify a stolen token offline.
7: //
8: // A placeholder ships committed so a developer can clone and run without
9: // per-developer secret setup. Every other environment MUST override it via
10: // REFRESH_TOKEN_PEPPER. `assertPepperConfigured()` is the guard that makes a
11: // missed override fail loudly at boot instead of silently shipping a secret
12: // that is printed in the source.
13: 
14: export const DEV_PEPPER_PLACEHOLDER =
15:   "dev-only-pepper-replace-in-non-dev-environments-via-env-var";
16: 
17: export const DEFAULT_LIFETIME_MS = 30 * 24 * 60 * 60 * 1000; // 30 days
18: 
19: export function getPepper() {
20:   const value = process.env.REFRESH_TOKEN_PEPPER ?? DEV_PEPPER_PLACEHOLDER;
21:   if (typeof value !== "string" || value.length === 0) {
22:     throw new Error("refresh token pepper is not configured");
23:   }
24:   return value;
25: }
