28:   const raw = process.env.REFRESH_TOKEN_LIFETIME_MS;
29:   const parsed = raw === undefined ? NaN : Number(raw);
30:   return Number.isFinite(parsed) && parsed > 0 ? parsed : DEFAULT_LIFETIME_MS;
