1: // A minimal in-memory row store with the two database behaviours this
2: // service actually depends on: transactions, and a per-row write lock.
3: //
4: // Deliberately not a real database. What the service needs to be correct
5: // about is the ORDERING guarantee, not the storage engine, and modelling it
6: // here keeps the whole fixture dependency-free and instant to run. The lock
7: // below is the in-process analogue of `SELECT ... FOR UPDATE`: two
8: // transactions that lock the same row are serialised, and the second one
9: // observes whatever the first one committed.
10: 
11: class Lock {
12:   #held = false;
13:   #waiters = [];
14: 
15:   async acquire() {
16:     if (!this.#held) {
17:       this.#held = true;
18:       return;
19:     }
20:     await new Promise((resolve) => this.#waiters.push(resolve));
21:   }
22: 
23:   release() {
24:     const next = this.#waiters.shift();
25:     if (next) next();
26:     else this.#held = false;
27:   }
28: }
29: 
30: export class TokenStore {
31:   #rows = [];
32:   #locks = new Map();
33:   #txLock = new Lock();
34: 
35:   /** Every row, for assertions. Returns copies so callers cannot mutate state. */
36:   all() {
37:     return this.#rows.map((r) => ({ ...r }));
38:   }
39: 
40:   insert(row) {
41:     this.#rows.push({
42:       tokenHash: row.tokenHash,
43:       sessionId: row.sessionId,
44:       userId: row.userId,
45:       expiresAt: row.expiresAt,
46:       revokedAt: row.revokedAt ?? null,
47:       chainRevokedAt: row.chainRevokedAt ?? null,
48:       replacedByTokenHash: row.replacedByTokenHash ?? null,
49:     });
50:   }
51: 
52:   findByHash(tokenHash) {
53:     const row = this.#rows.find((r) => r.tokenHash === tokenHash);
54:     return row ? { ...row } : null;
55:   }
56: 
57:   updateByHash(tokenHash, patch) {
58:     let n = 0;
59:     for (const r of this.#rows) {
60:       if (r.tokenHash === tokenHash) {
61:         Object.assign(r, patch);
62:         n += 1;
63:       }
64:     }
65:     return n;
66:   }
67: 
68:   updateBySession(sessionId, patch) {
69:     let n = 0;
70:     for (const r of this.#rows) {
71:       if (r.sessionId === sessionId) {
72:         Object.assign(r, patch);
73:         n += 1;
74:       }
75:     }
76:     return n;
77:   }
78: 
79:   /**
80:    * Run `fn` inside a transaction. `fn` receives a handle exposing the same
81:    * operations plus `lockByHash`, which blocks until any other transaction
82:    * holding that row's lock has finished.
83:    */
84:   async transaction(fn) {
85:     await this.#txLock.acquire();
86:     const held = [];
87:     try {
88:       const handle = {
89:         lockByHash: async (tokenHash) => {
90:           let lock = this.#locks.get(tokenHash);
91:           if (!lock) {
92:             lock = new Lock();
93:             this.#locks.set(tokenHash, lock);
94:           }
95:           // Releasing the coarse transaction lock while waiting on the row
96:           // lock is what lets a second transaction make progress and is what
97:           // makes the concurrency behaviour observable at all.
98:           this.#txLock.release();
99:           await lock.acquire();
100:           held.push(lock);
101:           await this.#txLock.acquire();
102:           return this.findByHash(tokenHash);
103:         },
104:         insert: (row) => this.insert(row),
105:         findByHash: (h) => this.findByHash(h),
106:         updateByHash: (h, patch) => this.updateByHash(h, patch),
107:         updateBySession: (s, patch) => this.updateBySession(s, patch),
108:       };
109:       return await fn(handle);
110:     } finally {
111:       for (const lock of held) lock.release();
112:       this.#txLock.release();
113:     }
114:   }
115: }

